CREATE OR REPLACE FUNCTION public.wear_walk(p_world uuid, p_x0 double precision, p_y0 double precision, p_x1 double precision, p_y1 double precision, p_uid uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare far double precision; n int; i int; t double precision;
        fx int; fy int; tx int; ty int; spans boolean;
begin
  far := sqrt(power(p_x1 - p_x0, 2) + power(p_y1 - p_y0, 2));
  if far <= 0.0001 then return; end if;
  spans := exists (select 1 from bridge b where b.world_id = p_world);
  fx := floor(p_x0)::int; fy := floor(p_y0)::int;
  n := least(walk_samples()::int, greatest(1, ceil(far * 2)::int));
  for i in 1..n loop
    t := i::double precision / n;
    tx := floor(p_x0 + (p_x1 - p_x0) * t)::int;
    ty := floor(p_y0 + (p_y1 - p_y0) * t)::int;
    if tx <> fx or ty <> fy then
      if abs(tx - fx) <= 1 and abs(ty - fy) <= 1
         and (not spans or not exists (select 1 from bridge b where b.world_id = p_world and b.kind <> 'aqueduct'
                                          and tx between least(b.ax, b.bx) - 1 and greatest(b.ax, b.bx) + 1
                                          and ty between least(b.ay, b.by) - 1 and greatest(b.ay, b.by) + 1
                                          and bridge_deck_lane(b, tx, ty) is not null)) then
        perform wear_step(p_world, tx, ty, p_uid);
      end if;
      fx := tx; fy := ty;
    end if;
  end loop;
end $function$
